template<class charT, class traits = std::char_traits<charT>> class basic_istream : virtual public basic_ios<charT, traits> { /* ... */ };
// Implementation notes: The traits parameter (e.g., std::char_traits<charT>) defines operations like:
// - traits::eq_int_type(int_type c1, int_type c2) for comparing character representations.
// - traits::to_int_type(char_type c) for converting a character to an integer type.
// These are used in input extraction loops, e.g., in std::getline, where the compiler inlines these for performance.

code_example:
#include <iostream>
#include <string>

int main() {
    std::string line;
    // Extract line until delimiter (e.g., newline) or EOF
    std::getline(std::cin, line);
    std::cout << "Extracted: " << line << std::endl;
    return 0;
}
